#!/usr/bin/env node
// Generated by local-expo-build v0.4.3
// To upgrade: npx local-expo-build update-scripts
/**
 * Prints the absolute paths (and sizes) of all freshly built APKs / AABs.
 * Runs at the very end of the build chain so you always know what was produced.
 * Generated by local-expo-build.
 *
 * Usage: node scripts/print-artifact.js (apk|aab)
 */
const fs = require("fs");
const path = require("path");

const kind = (process.argv[2] || "").toLowerCase();
if (kind !== "apk" && kind !== "aab") {
	console.error("Usage: node scripts/print-artifact.js (apk|aab)");
	process.exit(1);
}

const PROJECT_ROOT = path.resolve(__dirname, "..");
const searchDir =
	kind === "aab"
		? path.join(
				PROJECT_ROOT,
				"android",
				"app",
				"build",
				"outputs",
				"bundle",
				"release",
			)
		: path.join(
				PROJECT_ROOT,
				"android",
				"app",
				"build",
				"outputs",
				"apk",
				"release",
			);

if (!fs.existsSync(searchDir)) {
	console.error("Expected output directory not found at:");
	console.error("  " + searchDir);
	console.error("Check the Gradle output above for errors.");
	process.exit(1);
}

// Belirtilen dizin ve alt dizinlerdeki tüm .apk veya .aab dosyalarını rekürsif olarak bulur
function findFiles(dir, ext, fileList = []) {
	const files = fs.readdirSync(dir);
	files.forEach((file) => {
		const filePath = path.join(dir, file);
		if (fs.statSync(filePath).isDirectory()) {
			findFiles(filePath, ext, fileList);
		} else if (file.toLowerCase().endsWith(ext)) {
			fileList.push(filePath);
		}
	});
	return fileList;
}

const extension = kind === "aab" ? ".aab" : ".apk";
const artifacts = findFiles(searchDir, extension);

if (artifacts.length === 0) {
	console.error("No " + kind.toUpperCase() + " files found in:");
	console.error("  " + searchDir);
	process.exit(1);
}

console.log("");
console.log(
	"Build artifacts (" +
		kind.toUpperCase() +
		", total " +
		artifacts.length +
		" found):",
);
artifacts.forEach((artifact) => {
	const stat = fs.statSync(artifact);
	const sizeMb = (stat.size / 1024 / 1024).toFixed(2);
	console.log("  " + artifact + " (" + sizeMb + " MB)");
});
console.log("");
